/*
 * A349749  Odd numbers k for which the 3-adic valuation of sigma(k) is equal
 *          to the 3-adic valuation of k, where sigma is the sum of divisors
 *          function.
 * https://oeis.org/A349749
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th odd integer k such that v₃(σ(k)) = v₃(k) * (σ =
 *            sum of divisors; v₃ is the exponent of 3 in the prime
 *            factorisation). * The sequence is generated by a simple sieve of
 *            odd numbers up to a limit * sufficient to cover 10000 terms
 * Range:     u8 n <= 39, u16 n <= 68, u32 n <= 68, u64 n <= 68, u128 n <= 68,
 *            big any n
 * Helpers:   seq_alloc_new_array, sigma_of
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

#include "../utils/sigma_of.h"
#include "../utils/seq_alloc_new_array.h"

static const size_t INIT_CAP = 200000;          /* enough for n ≈ 1e4 */
static seq_t *terms = NULL;                    /* array of found terms      */
static size_t terms_count = 0;                 /* number of terms stored    */
static idx_t current_k = 1;                    /* next odd number to test   */

/* initialise the terms array on first use */
static void init_terms(void) {
    if (!terms) {
        terms = seq_alloc_new_array(INIT_CAP);
    }
}

/* return the n-th term of the sequence (1‑based index) */
seq_t a(idx_t n) {
    if (!terms) init_terms();

    /* grow the search until we have at least n terms */
    while (terms_count < (size_t)n) {
        /* test current_k (odd, >=1) */
        idx_t m = 0;                /* v₃(k) */
        idx_t kk = current_k;
        while (kk % 3 == 0) {
            kk /= 3;
            m++;
        }
        idx_t N = kk;               /* odd part of k (not divisible by 3) */

        seq_t sigmaN = sigma_of(N);

        /* compute v₃(σ(N)) */
        idx_t m2 = 0;
        while (sigmaN % 3 == 0) {
            sigmaN /= 3;
            m2++;
        }

        if (m2 == m) {
            /* k satisfies the condition; store it */
            terms[terms_count++] = current_k;
        }

        current_k += 2;             /* next odd number */
    }

    return terms[(size_t)n - 1];
}
